def index_of_first_new_max(lst):
    res = []
    cur_max = None
    for i, x in enumerate(lst):
        if cur_max is None or x > cur_max:
            res.append(i)
            cur_max = x
    return res

def alternating_sum_plus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += x if i % 2 == 0 else -x
    return total

def alternating_sum_minus_first(lst):
    total = 0
    for i, x in enumerate(lst):
        total += -x if i % 2 == 0 else x
    return total

def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    diffs = [abs(lst[i + 1] - lst[i]) for i in range(len(lst) - 1)]
    total = 0
    for i, d in enumerate(diffs):
        total += d if i % 2 == 0 else -d
    return total

def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    diffs = [lst[i + 1] - lst[i] for i in range(n - 1)]
    if any(d == 0 for d in diffs):
        return False
    for i in range(1, len(diffs)):
        if (diffs[i] > 0) == (diffs[i - 1] > 0):
            return False
    return True

def sign_changes_count(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    count = 0
    for i in range(len(lst) - 1):
        if sign(lst[i]) != sign(lst[i + 1]):
            count += 1
    return count

def is_arithmetic_sequence(lst):
    if len(lst) <= 2:
        return True
    diff = lst[1] - lst[0]
    for i in range(2, len(lst)):
        if lst[i] - lst[i - 1] != diff:
            return False
    return True

def is_geometric_sequence(lst):
    n = len(lst)
    if n <= 1:
        return True
    ratio = lst[1] / lst[0]
    for i in range(1, n):
        if lst[i] / lst[i - 1] != ratio:
            return False
    return True
